$$\begin{array}{l}
I_{\text {net }}=2\left(I_{1}+I_{2}\right) \\
=2\left(\frac{M^{\prime} R^{2}}{4}+\frac{M^{\prime} \ell^{2}}{12}\right)+2\left(\frac{M^{\prime} R^{2}}{2}+M^{\prime}\left(\frac{\ell}{2}\right)^{2}\right) \\
=\frac{M^{\prime} R^{2}}{2}+\frac{M^{\prime} R^{2}}{6}+M^{\prime} R^{2}+\frac{M^{\prime} \ell^{2}}{2} \\
=\frac{3 M^{\prime} R^{2}}{2}+\frac{2 M^{\prime} \ell^{2}}{3}
